<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --card: #ffffff;
        --text: #172033;
        --muted: #5c667a;
        --border: #d8deea;
        --primary: #3457d5;
        --primary-dark: #2442ad;
        --ring: #7aa2ff;
        --shadow: 0 24px 70px rgba(25, 36, 76, 0.16);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top left, rgba(52, 87, 213, 0.18), transparent 34rem),
          linear-gradient(135deg, #f7f9ff 0%, var(--bg) 52%, #eef3ff 100%);
        color: var(--text);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: #fff;
        padding: 0.75rem 1rem;
        text-decoration: none;
        transition: transform 160ms ease;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: clamp(1rem, 4vw, 3rem);
      }

      .support-card {
        width: min(100%, 45rem);
        overflow: hidden;
        border: 1px solid rgba(216, 222, 234, 0.85);
        border-radius: 2rem;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .card-header {
        padding: clamp(1.75rem, 5vw, 3rem) clamp(1.5rem, 5vw, 3rem) 1.25rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary-dark);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        max-width: 12ch;
        font-size: clamp(2.2rem, 8vw, 4.5rem);
        line-height: 0.94;
        letter-spacing: -0.07em;
      }

      .intro {
        margin: 1.15rem 0 0;
        max-width: 36rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.65;
      }

      form {
        display: grid;
        gap: 1.15rem;
        padding: 0 clamp(1.5rem, 5vw, 3rem) clamp(1.75rem, 5vw, 3rem);
      }

      .required-note {
        margin: 0 0 0.25rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 750;
      }

      .required-mark {
        color: var(--primary-dark);
        font-weight: 900;
      }

      input {
        width: 100%;
        min-height: 3.35rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: #fff;
        color: var(--text);
        font: inherit;
        padding: 0.85rem 1rem;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
      }

      input:hover {
        border-color: #aeb8ce;
      }

      input:focus {
        border-color: var(--primary);
        outline: 3px solid rgba(122, 162, 255, 0.55);
        outline-offset: 2px;
        box-shadow: 0 0 0 5px rgba(52, 87, 213, 0.08);
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.92rem;
        line-height: 1.5;
      }

      button {
        justify-self: start;
        min-height: 3.25rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        color: #fff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        padding: 0.85rem 1.35rem;
        box-shadow: 0 14px 28px rgba(52, 87, 213, 0.25);
        transition: box-shadow 160ms ease, transform 160ms ease;
      }

      button:hover {
        box-shadow: 0 18px 34px rgba(52, 87, 213, 0.32);
        transform: translateY(-1px);
      }

      button:focus {
        outline: 3px solid var(--ring);
        outline-offset: 4px;
      }

      button:active {
        transform: translateY(0);
      }

      @media (max-width: 38rem) {
        .page-shell {
          place-items: stretch;
          padding: 0;
        }

        .support-card {
          min-height: 100vh;
          border: 0;
          border-radius: 0;
        }

        button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        .support-card,
        input,
        button {
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const Field = ({ id, label, type = "text", required = false, autocomplete, helperText }) => `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            ${required ? "required" : ""}
            ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
            ${helperText ? `aria-describedby="${id}-help"` : ""}
          >
          ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
        </div>
      `;

      const SupportContactForm = () => `
        <main class="page-shell" id="main-content">
          <section class="support-card" aria-labelledby="support-title">
            <header class="card-header">
              <p class="eyebrow">Support</p>
              <h1 id="support-title">How can we help?</h1>
              <p class="intro">
                Tell us where to reach you and our support team will follow up with the right next steps.
              </p>
            </header>

            <form action="#" method="post">
              <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>
              ${Field({
                id: "full-name",
                label: "Full name",
                required: true,
                autocomplete: "name"
              })}
              ${Field({
                id: "email-address",
                label: "Email address",
                type: "email",
                required: true,
                autocomplete: "email"
              })}
              ${Field({
                id: "phone-number",
                label: "Phone number",
                type: "tel",
                autocomplete: "tel",
                helperText: "Use international format, for example +1 555 123 4567."
              })}
              <button type="submit">Contact support</button>
            </form>
          </section>
        </main>
      `;

      document.getElementById("root").innerHTML = SupportContactForm();
    </script>
  </body>
</html>
