const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  let browser;
  try {
    browser = await chromium.launch();
  } catch (error) {
    console.log(JSON.stringify({ launch_error: String(error).split('\n')[0] }, null, 2));
    process.exit(2);
  }
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  const wcag = result.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = result.violations.filter(v => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch(error => {
  console.error(error);
  process.exit(2);
});
